# Phase 02: a customer rates a resolved ticket

Makes work: `portal.rateTicket(store, customer, id, score)` stores the score and time on a resolved ticket of the customer's organisation, once. Shown by the new tests in `test/rating.test.js`.
Blocked by: phase 01. Class: COUNCIL (tenant scoping is a hot path, so independent review is a step).

## Context
- Requirements 1 to 3; acceptance criteria 1 to 5. Pattern to follow: `getMyTicket` returns `null` for another organisation's ticket (`src/portal.js:10-12`).
- The store has no conditional write. A read then `updateTicket` lets two submits both succeed, so add one atomic method; the Postgres adapter implements it as `UPDATE ... WHERE id = $1 AND rating_score IS NULL`.

## Files
- Modify `src/store.js` (add `rateTicketOnce`), `src/tickets.js` (add `rating_score: null, rated_at: null` in `createTicket`, after `resolved_at`), `src/portal.js` (add `rateTicket`, export it).
- Create `test/rating.test.js`.

## Steps
- [ ] 1. Write `test/rating.test.js`:
  ```js
  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const { createStore } = require('../src/store');
  const { createTicket, resolveTicket } = require('../src/tickets');
  const portal = require('../src/portal');

  const acme = { id: 7, orgId: 1 };
  const globex = { id: 9, orgId: 2 };
  const now = new Date(Date.UTC(2026, 0, 5));

  function resolved(store) {
    const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now });
    resolveTicket(store, t.id, 41, { now });
    return t.id;
  }

  test('a customer rates a resolved ticket of their organisation', () => {
    const store = createStore();
    const id = resolved(store);
    portal.rateTicket(store, acme, id, 4, { now });
    const t = store.getTicket(id);
    assert.equal(t.rating_score, 4);
    assert.equal(t.rated_at, now.toISOString());
  });

  test('a score that is not a whole number from 1 to 5 is refused', () => {
    const store = createStore();
    const id = resolved(store);
    for (const bad of [0, 6, 3.5, '4', null, undefined, NaN]) {
      assert.throws(() => portal.rateTicket(store, acme, id, bad, { now }), /whole number from 1 to 5/);
    }
    assert.equal(store.getTicket(id).rating_score, null);
  });

  test('an open or pending ticket cannot be rated', () => {
    const store = createStore();
    const open = createTicket(store, { orgId: 1, customerId: 7, subject: 'a', body: 'x', now });
    assert.throws(() => portal.rateTicket(store, acme, open.id, 5, { now }), /cannot rate a open ticket/);
    store.updateTicket(open.id, { status: 'pending' });
    assert.throws(() => portal.rateTicket(store, acme, open.id, 5, { now }), /cannot rate a pending ticket/);
  });

  test('a closed ticket cannot be rated', () => {
    const store = createStore();
    const id = resolved(store);
    store.updateTicket(id, { status: 'closed' });
    assert.throws(() => portal.rateTicket(store, acme, id, 5, { now }), /cannot rate a closed ticket/);
  });

  test('a second rating is refused and the first stays', () => {
    const store = createStore();
    const id = resolved(store);
    portal.rateTicket(store, acme, id, 4, { now });
    assert.throws(() => portal.rateTicket(store, acme, id, 1, { now: new Date(now.getTime() + 1000) }), /already rated/);
    const t = store.getTicket(id);
    assert.equal(t.rating_score, 4);
    assert.equal(t.rated_at, now.toISOString());
  });

  test('another organisation gets the same answer as for a missing ticket', () => {
    const store = createStore();
    const id = resolved(store);
    assert.equal(portal.rateTicket(store, globex, id, 5, { now }), null);
    assert.equal(portal.rateTicket(store, globex, 9999, 5, { now }), null);
    assert.equal(portal.rateTicket(store, globex, id, 99, { now }), null); // a bad score does not reveal the ticket
    assert.equal(store.getTicket(id).rating_score, null);
  });
  ```
