  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const { createStore } = require('../src/store');
  const { createTicket, assignTicket } = require('../src/tickets');
  const { summariseRatings } = require('../src/jobs/agent-rating-summary');

  const DAY = 24 * 60 * 60 * 1000;
  const now = new Date(Date.UTC(2026, 0, 20, 2, 0));

  function rated(store, agentId, score, daysAgo) {
    const t = createTicket(store, { orgId: 1, customerId: 7, subject: 's', body: 'x', now });
    if (agentId) assignTicket(store, t.id, agentId);
    store.updateTicket(t.id, { status: 'resolved', rating_score: score, rated_at: new Date(now.getTime() - daysAgo * DAY).toISOString() });
