  'use strict';
  // Nightly. For each agent, how many ratings their tickets received in the past seven days, and the average score.
  // A ticket counts for its owner when the job runs; an unowned ticket counts for nobody.
  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function summariseRatings(store, { now = new Date() } = {}) {
    const since = now.getTime() - WINDOW_DAYS * DAY;
    const byAgent = new Map();
    for (const t of store.listTickets()) {
      if (t.rating_score == null || !t.owner_id) continue;
      const at = new Date(t.rated_at).getTime();
      if (at < since || at > now.getTime()) continue;
      const scores = byAgent.get(t.owner_id) || [];
      scores.push(t.rating_score);
      byAgent.set(t.owner_id, scores);
    }
    const weekEnding = now.toISOString().slice(0, 10);
    const rows = [...byAgent].sort((a, b) => a[0] - b[0]).map(([agentId, scores]) => ({
      agent_id: agentId,
      week_ending: weekEnding,
      ratings: scores.length,
      average: Math.round((scores.reduce((s, x) => s + x, 0) / scores.length) * 100) / 100,
    }));
    for (const row of rows) store.saveAgentSummary(row);
    return rows;
  }

  module.exports = { summariseRatings, WINDOW_DAYS };
  ```
